from functools import lru_cache

@lru_cache(None)

def F(a, b):
    if a >= b or a == 100:
        return a == b
    count = 0
    x = a % 10 
    if x != 0:
        count += F(a + x, b)
    x = a % 68  
    if x != 0:
        count += F(a + x, b)
    x = a ** 2 
    if x != a:
        count += F(x, b)
    return count
print(F(2, 68) * F(68, 680))
